#!/usr/bin/env python3
"""The reference differential-drive odometry for odometry-nv's vector tests.

Run it to write tests/odometry_vector_tests.nv:

    python3 tests/fixtures/odometry_reference.py > tests/odometry_vector_tests.nv

The reference is float64 and is written from the textbook arc formula,
not from the chord-and-sinc form the package uses: for a step that turns
by dtheta along a circle of radius R = d / dtheta,

    x' = x + R (sin(theta + dtheta) - sin(theta))
    y' = y - R (cos(theta + dtheta) - cos(theta))

and a straight line when dtheta is zero.  The counter step is Python's
modular arithmetic on integers, and the heading is wrapped with atan2.
The wheel counts are a pseudo-random walk that crosses the sixteen-bit
wrap on both wheels.  The commands are clipped and scaled by the same
rule the package states, written out separately.
"""

import math


class Lcg:
    def __init__(self, seed):
        self.s = seed

    def uniform(self):
        self.s = (1103515245 * self.s + 12345) % 2147483648
        return self.s / 2147483648.0


def lst(xs):
    return "[" + ", ".join(repr(float(v)) for v in xs) + "]"


R, L, TPR, BITS = 0.0325, 0.287, 1440, 16
MOD = 1 << BITS


def metres(ticks):
    return ticks * 2.0 * math.pi * R / TPR


def sequence(steps, dt):
    rng = Lcg(2026)
    left, right = 65500, 100
    counts = [(left, right)]
    pose = (0.0, 0.0, 0.0)
    rows = []
    prev = (left, right)
    for k in range(steps):
        # A drive that speeds up, swings left and then right.
        base = 40 + 30 * math.sin(0.15 * k)
        turn = 25 * math.sin(0.07 * k + 0.5)
        dl = int(round(base - turn + 6 * (rng.uniform() - 0.5)))
        dr = int(round(base + turn + 6 * (rng.uniform() - 0.5)))
        left = (left + dl) % MOD
        right = (right + dr) % MOD
        counts.append((left, right))
        half = MOD // 2
        tl = (left - prev[0] + half) % MOD - half
        tr = (right - prev[1] + half) % MOD - half
        prev = (left, right)
        sl, sr = metres(tl), metres(tr)
        d = 0.5 * (sl + sr)
        dtheta = (sr - sl) / L
        x, y, th = pose
        if abs(dtheta) > 1e-12:
            rad = d / dtheta
            x = x + rad * (math.sin(th + dtheta) - math.sin(th))
            y = y - rad * (math.cos(th + dtheta) - math.cos(th))
        else:
            x = x + d * math.cos(th)
            y = y + d * math.sin(th)
        th = math.atan2(math.sin(th + dtheta), math.cos(th + dtheta))
        pose = (x, y, th)
        rows += [x, y, th, d / dt, dtheta / dt]
    return counts, rows


def command(v, w, max_linear, max_angular, max_wheel):
    v = max(-max_linear, min(max_linear, v))
    w = max(-max_angular, min(max_angular, w))
    left = (v - w * L / 2) / R
    right = (v + w * L / 2) / R
    peak = max(abs(left), abs(right))
    if peak > max_wheel:
        left, right = left * max_wheel / peak, right * max_wheel / peak
    return left, right


def emit():
    steps, dt = 80, 0.02
    counts, rows = sequence(steps, dt)
    flat_counts = [c for pair in counts for c in pair]
    cmds = [(0.3, 0.0), (0.0, 1.5), (0.5, -1.0), (-0.4, 0.8), (1.5, 0.0), (0.2, 6.0),
            (0.8, 3.0), (-1.2, -4.0), (0.0, 0.0), (0.6, 2.0), (0.79, 0.1), (0.05, -2.9)]
    table = []
    for v, w in cmds:
        wl, wr = command(v, w, 0.8, 3.0, 30.0)
        table += [v, w, wl, wr]
    print(f'''// odometry_vector_tests.nv — the odometer and the command against a
// reference, step by step.
//
// GENERATED by tests/fixtures/odometry_reference.py; do not edit by hand.
// The reference is float64 and takes the arc of a step from the
// textbook formula, `x' = x + R (sin(theta + dtheta) - sin theta)`, which
// shares no expression with the package's chord form.  The wheel counts
// are a pseudo-random walk of two sixteen-bit counters that both cross
// the wrap, and the counter step is Python's modular integer
// arithmetic.  The commands are clipped and scaled by the rule the
// package states, written out separately.
//
// The tolerance on a pose is `TOL`, relative to one plus the magnitude
// of the number: binary32 carries about seven digits, the eighty steps
// agree with the float64 reference to better than 1e-6, and 1e-5 is
// ten times that.

use std.test
use odometry

const TOL = 0.00001

// Whether a binary32 answer is within `TOL` of the reference's, relative
// to one plus the reference's magnitude.
fn near(got: fp32, want: Float) -> Bool
    math.abs((got as Float) - want) <= TOL * (1.0 + math.abs(want))

fn machine() -> Params
    odometry.params({R!r}, {L!r}, {TPR})

// The two counters at each of the 81 samples: left then right.
fn counts() -> [Int]
    {flat_counts!r}

// Per step: x, y, theta, v, w after the sample.
fn want() -> [Float]
    {lst(rows)}

// Per command: v, w, then the left and the right wheel speed under
// limits of 0.8 m/s, 3 rad/s and 30 rad/s at the wheel.
fn commands() -> [Float]
    {lst(table)}

@test
fn test_the_odometer_follows_the_reference_arc_step_by_step_across_the_counter_wrap()
    let c = counts()
    let w = want()
    var o = odometry.odometer(machine(), {BITS})
    o = odometry.update(o, c[0], c[1], {dt!r} as fp32)
    test.assert(o.started)
    for k in 0..{steps}
        o = odometry.update(o, c[(k + 1) * 2], c[(k + 1) * 2 + 1], {dt!r} as fp32)
        test.assert(near(o.pose.x, w[k * 5]))
        test.assert(near(o.pose.y, w[k * 5 + 1]))
        test.assert(near(o.pose.theta, w[k * 5 + 2]))
        test.assert(near(o.twist.v, w[k * 5 + 3]))
        test.assert(near(o.twist.w, w[k * 5 + 4]))

@test
fn test_a_velocity_command_becomes_the_reference_wheel_speeds_under_limits()
    let t = commands()
    let lim = odometry.limits(0.8, 3.0, 30.0)
    for i in 0..{len(cmds)}
        let wheels = odometry.wheel_speeds(machine(), odometry.twist(t[i * 4] as fp32, t[i * 4 + 1] as fp32), lim)
        test.assert(near(wheels.left, t[i * 4 + 2]))
        test.assert(near(wheels.right, t[i * 4 + 3]))
''')


if __name__ == "__main__":
    emit()
